-- Apply only after the PR is merged and all media return HTTP 200 in production.
BEGIN;
DO $publish$
DECLARE
 payload jsonb := $content$[{"language":"es","slug":"tamal-tolimense","title":"Tamal tolimense tradicional en hoja de plátano","seo":{"title":"Tamal tolimense tradicional en hoja de plátano","description":"Prepara tamal tolimense con masa de arroz y maíz, cerdo, pollo, huevo y verduras. Receta en hoja de plátano, con tiempos claros de cocción al vapor.","faq":[{"q":"¿Puedo usar maíz molido en lugar de harina precocida?","a":"Sí, pero exige otro proceso de remojo y cocción. Las cantidades y los tiempos de esta receta corresponden a harina de maíz blanco precocida."},{"q":"¿Por qué la masa queda blanda?","a":"Puede faltar cocción o reposo. Comprueba el agua de la vaporera y prolonga la cocción en tandas de 15 minutos; deja reposar los paquetes antes de abrirlos."},{"q":"¿Puedo armarlos desde la víspera?","a":"Sí. Refrigéralos de inmediato a 4 °C o menos y cocínalos dentro de las 24 horas desde que adobaste las carnes. Cuenta las 3 horas a partir del vapor continuo."}],"image_alt":"Tamal tolimense tradicional en hoja de plátano","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-16x9.webp"],"additional_time_minutes":735},"summary":"El tamal del Tolima reúne masa de maíz, arroz y arvejas con cerdo, pollo, huevo, papa y zanahoria. Se arma como un paquete redondo en hoja de plátano y se cocina lentamente al vapor.","ingredients":[{"amount":"350","unit":"g","name":"harina de maíz blanco precocida, sin azúcar ni sal"},{"amount":"250","unit":"g","name":"arroz blanco seco"},{"amount":"600","unit":"g","name":"carne magra de pierna de cerdo deshuesada"},{"amount":"600","unit":"g","name":"muslo de pollo deshuesado y sin piel"},{"amount":"4","unit":"unidad","name":"huevos grandes, unos 200 g sin cáscara"},{"amount":"400","unit":"g","name":"papa pelada"},{"amount":"200","unit":"g","name":"zanahoria pelada"},{"amount":"160","unit":"g","name":"arvejas verdes congeladas"},{"amount":"200","unit":"g","name":"cebolla larga"},{"amount":"20","unit":"g","name":"ajo pelado"},{"amount":"40","unit":"g","name":"aceite vegetal"},{"amount":"3","unit":"g","name":"achiote molido puro"},{"amount":"4","unit":"g","name":"comino molido"},{"amount":"16","unit":"g","name":"sal"},{"amount":"1","unit":"g","name":"pimienta negra molida"},{"amount":"1000","unit":"ml","name":"caldo de pollo sin sal, frío"},{"amount":"450","unit":"ml","name":"agua para el arroz"},{"amount":"100","unit":"ml","name":"agua para el adobo"},{"amount":"16","unit":"unidad","name":"hojas de plátano de unos 40 × 40 cm, aptas para cocinar"}],"steps":[{"title":"Corta el cerdo","content":"Corta los 600 g de cerdo en 8 trozos iguales."},{"title":"Corta el pollo","content":"Corta los 600 g de pollo en 8 trozos iguales."},{"title":"Pica la cebolla","content":"Pica finamente los 200 g de cebolla larga."},{"title":"Pica el ajo","content":"Pica finamente los 20 g de ajo."},{"title":"Mezcla el adobo","content":"Mezcla 100 g de cebolla, todo el ajo, 2 g de comino, 10 g de sal, 1 g de pimienta y 100 ml de agua."},{"title":"Adoba las carnes","content":"Unta el cerdo y el pollo con todo el adobo en un recipiente con tapa.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-06.webp","image_alt":"Adoba las carnes"},{"title":"Refrigera","content":"Mantén las carnes tapadas en la nevera a 4 °C o menos durante 12 horas."},{"title":"Cuece los huevos","content":"Cuece los 4 huevos en agua hirviendo suave durante 10 minutos."},{"title":"Enfría los huevos","content":"Pasa los huevos a agua fría durante 5 minutos."},{"title":"Pela los huevos","content":"Retira la cáscara de los huevos."},{"title":"Parte los huevos","content":"Corta cada huevo por la mitad para obtener 8 mitades."},{"title":"Corta la papa","content":"Corta los 400 g de papa en rodajas de 5 mm."},{"title":"Corta la zanahoria","content":"Corta los 200 g de zanahoria en rodajas de 3 mm."},{"title":"Precocina el arroz","content":"Cocina los 250 g de arroz con 450 ml de agua, tapado y a fuego bajo, durante 12 minutos desde el hervor; debe quedar algo firme.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-14.webp","image_alt":"Precocina el arroz"},{"title":"Sofríe la cebolla","content":"Cocina los 100 g de cebolla restantes con los 40 g de aceite a fuego medio durante 5 minutos."},{"title":"Sazona el sofrito","content":"Incorpora al sofrito 3 g de achiote, 2 g de comino y 6 g de sal durante 30 segundos."},{"title":"Mezcla la harina","content":"Mezcla los 350 g de harina de maíz con los 1000 ml de caldo frío hasta eliminar los grumos."},{"title":"Espesa la masa","content":"Cocina la mezcla de maíz a fuego medio-bajo durante 5–8 minutos, removiendo hasta obtener una crema espesa y extendible."},{"title":"Integra el relleno","content":"Mezcla la masa con el arroz, los 160 g de arvejas y todo el sofrito.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-19.webp","image_alt":"Integra el relleno"},{"title":"Lava las hojas","content":"Lava las 16 hojas de plátano con agua potable."},{"title":"Ablanda las hojas","content":"Sumerge las hojas en agua caliente durante 2 minutos, hasta que sean flexibles."},{"title":"Seca las hojas","content":"Seca las hojas con un paño limpio."},{"title":"Prepara las bases","content":"Cruza 2 hojas por cada tamal, con la cara más lisa hacia arriba."},{"title":"Reparte la masa","content":"Distribuye la mitad de la masa entre las 8 bases, dejando espacio alrededor."},{"title":"Añade las carnes","content":"Coloca 1 trozo de cerdo y 1 de pollo por tamal, repartiendo también el adobo."},{"title":"Añade las verduras","content":"Reparte la papa y la zanahoria entre los 8 tamales."},{"title":"Añade el huevo","content":"Coloca media unidad de huevo en cada tamal.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-27.webp","image_alt":"Añade el huevo"},{"title":"Cubre el relleno","content":"Distribuye la masa restante sobre los rellenos."},{"title":"Cierra las hojas","content":"Recoge los bordes hacia arriba para formar paquetes redondos bien cerrados."},{"title":"Ata los tamales","content":"Asegura cada paquete con hilo de cocina, sin apretar la masa.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-30.webp","image_alt":"Ata los tamales"},{"title":"Prepara la vaporera","content":"Pon agua bajo la rejilla de una olla grande, sin que alcance los tamales."},{"title":"Acomoda los paquetes","content":"Coloca los tamales en la rejilla con el cierre hacia arriba y espacio para el vapor."},{"title":"Cocina al vapor","content":"Cocina con tapa durante 3 horas desde que salga vapor continuo; mantén el hervor y repón agua hirviendo por el lateral cuando haga falta.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-33.webp","image_alt":"Cocina al vapor"},{"title":"Comprueba la cocción","content":"Mide el centro y el pollo de un tamal con termómetro: deben alcanzar al menos 74 °C y la masa debe estar firme; si falta, continúa al vapor en tandas de 15 minutos."},{"title":"Deja reposar","content":"Deja los paquetes fuera de la olla durante 15 minutos."},{"title":"Retira el hilo","content":"Retira el hilo de cocina de cada paquete."},{"title":"Abre los tamales","content":"Abre las hojas con cuidado del vapor."},{"title":"Sirve","content":"Sirve un tamal caliente por persona; la hoja no se come.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","image_alt":"Tamal tolimense tradicional en hoja de plátano"}],"notes":"<p>Usa harina de maíz blanco precocida, no maicena ni harina para tortillas ni masarepa ya sazonada. El arroz se incorpora parcialmente cocido y conserva su grano dentro de la masa. Las hojas congeladas deben estar descongeladas antes de comenzar. Usa hilo de cocina apto para alimentos. El agua de huevos, hojas y vaporera es adicional y no forma parte del caldo. Una vaporera de dos niveles permite acomodar 8 tamales sin comprimirlos. Refrigera las sobras antes de 2 horas en recipientes poco profundos; consúmelas en 3–4 días o congélalas hasta 2 meses. Recalienta al vapor hasta 74 °C en el centro.</p>","author":"Néstor Bastidas","category":"Platos principales","cuisine":"Colombiana","difficulty":"Intermedia","servings":8,"public_path":"/es/receta/tamal-tolimense","prep_time_minutes":90,"cook_time_minutes":225,"marinate_time_minutes":720,"rest_time_minutes":15,"total_time_minutes":1050,"nutrition":{"calories":621.3,"protein_g":41.5,"carbs_g":75.6,"fat_g":16.6,"serving_size":"1 tamal (1 de 8)","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"Suma de nutrientes de ingredientes crudos según perfiles USDA, dividida entre las porciones; los zumos se aproximan a 1 g por ml.","note":"Estimación para 1 de 8 tamales, sin acompañamientos. Usa cerdo magro y harina de maíz blanco genérica como aproximación de la precocida. No incluye el caldo sin sal ni los 3 g de achiote; la marca de harina y el caldo pueden cambiar los valores. Las hojas no se comen."},"excerpt":"El tamal del Tolima reúne masa de maíz, arroz y arvejas con cerdo, pollo, huevo, papa y zanahoria. Se arma como un paquete redondo en hoja de plátano y se cocina lentamente al vapor.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","course":"Platos principales","keywords":["Tamal tolimense tradicional en hoja de plátano"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/ingredientes.webp","alt":"Tamal tolimense tradicional en hoja de plátano"}]},{"language":"en","slug":"colombian-tamales-tolima","title":"Colombian Tamales from Tolima","seo":{"title":"Colombian Tamales from Tolima","description":"Make Tolima-style Colombian tamales with rice and corn dough, pork, chicken, eggs and vegetables, wrapped in banana leaves and slowly steamed.","faq":[{"q":"Can I use freshly ground corn?","a":"Yes, but it needs a different soaking and cooking process. This recipe is measured and timed for precooked white corn flour."},{"q":"Why is the dough soft?","a":"It may need more cooking or resting. Check the steamer water and continue in 15-minute intervals, then rest the parcels before opening."},{"q":"Can I assemble them ahead?","a":"Yes. Refrigerate immediately at 4 °C or below and cook within 24 hours of marinating the meat. Start the 3-hour steaming time once steam flows steadily."}],"image_alt":"Colombian Tamales from Tolima","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-16x9.webp"],"additional_time_minutes":735},"summary":"These generous tamales from Tolima combine corn dough, rice and peas with pork, chicken, egg, potato and carrot. Banana leaves form round parcels that cook gently in steam.","ingredients":[{"amount":"350","unit":"g","name":"plain precooked white corn flour, without salt or sugar"},{"amount":"250","unit":"g","name":"uncooked white rice"},{"amount":"600","unit":"g","name":"lean boneless pork leg"},{"amount":"600","unit":"g","name":"boneless skinless chicken thighs"},{"amount":"4","unit":"piece","name":"large eggs, about 200 g without shells"},{"amount":"400","unit":"g","name":"peeled potatoes"},{"amount":"200","unit":"g","name":"peeled carrots"},{"amount":"160","unit":"g","name":"frozen green peas"},{"amount":"200","unit":"g","name":"spring onions"},{"amount":"20","unit":"g","name":"peeled garlic"},{"amount":"40","unit":"g","name":"vegetable oil"},{"amount":"3","unit":"g","name":"pure ground annatto"},{"amount":"4","unit":"g","name":"ground cumin"},{"amount":"16","unit":"g","name":"salt"},{"amount":"1","unit":"g","name":"ground black pepper"},{"amount":"1000","unit":"ml","name":"cold unsalted chicken stock"},{"amount":"450","unit":"ml","name":"water for the rice"},{"amount":"100","unit":"ml","name":"water for the marinade"},{"amount":"16","unit":"piece","name":"food-grade banana-leaf sheets, about 40 × 40 cm"}],"steps":[{"title":"Cut the pork","content":"Cut the 600 g pork into 8 equal pieces."},{"title":"Cut the chicken","content":"Cut the 600 g chicken into 8 equal pieces."},{"title":"Chop the onions","content":"Finely chop the 200 g spring onions."},{"title":"Chop the garlic","content":"Finely chop the 20 g garlic."},{"title":"Mix the marinade","content":"Combine 100 g spring onions, all the garlic, 2 g cumin, 10 g salt, 1 g pepper and 100 ml water."},{"title":"Coat the meat","content":"Coat the pork and chicken with all the marinade in a lidded container.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-06.webp","image_alt":"Coat the meat"},{"title":"Chill","content":"Refrigerate the covered meat at 4 °C or below for 12 hours."},{"title":"Boil the eggs","content":"Gently boil the 4 eggs in water for 10 minutes."},{"title":"Cool the eggs","content":"Place the eggs in cold water for 5 minutes."},{"title":"Peel the eggs","content":"Remove the eggshells."},{"title":"Halve the eggs","content":"Cut each egg in half to make 8 halves."},{"title":"Slice the potatoes","content":"Cut the 400 g potatoes into 5 mm slices."},{"title":"Slice the carrots","content":"Cut the 200 g carrots into 3 mm slices."},{"title":"Parcook the rice","content":"Cook the 250 g rice with 450 ml water, covered over low heat, for 12 minutes from boiling; it should still be slightly firm.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-14.webp","image_alt":"Parcook the rice"},{"title":"Cook the onions","content":"Cook the remaining 100 g spring onions in the 40 g oil over medium heat for 5 minutes."},{"title":"Season the onions","content":"Stir the 3 g annatto, 2 g cumin and 6 g salt into the onions for 30 seconds."},{"title":"Mix the corn flour","content":"Whisk the 350 g corn flour with the 1000 ml cold stock until smooth."},{"title":"Thicken the dough","content":"Cook the corn mixture over medium-low heat for 5–8 minutes, stirring until thick but spreadable."},{"title":"Combine the filling","content":"Mix the corn dough with the rice, 160 g peas and all the cooked onion mixture.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-19.webp","image_alt":"Combine the filling"},{"title":"Wash the leaves","content":"Wash the 16 banana-leaf sheets with drinking water."},{"title":"Soften the leaves","content":"Immerse the leaves in hot water for 2 minutes, until flexible."},{"title":"Dry the leaves","content":"Pat the leaves dry with a clean cloth."},{"title":"Lay out the leaves","content":"Cross 2 sheets for each tamal, smoother side facing up."},{"title":"Portion the dough","content":"Divide half the dough among the 8 leaf bases, leaving room around the edges."},{"title":"Add the meat","content":"Place 1 pork piece and 1 chicken piece on each base, dividing the marinade among them."},{"title":"Add the vegetables","content":"Divide the potatoes and carrots among the 8 tamales."},{"title":"Add the eggs","content":"Place half an egg in each tamal.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-27.webp","image_alt":"Add the eggs"},{"title":"Cover the filling","content":"Spoon the remaining dough over the fillings."},{"title":"Close the leaves","content":"Gather the edges upward into tightly closed round parcels."},{"title":"Tie the parcels","content":"Secure each parcel with kitchen string without squeezing the dough.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-30.webp","image_alt":"Tie the parcels"},{"title":"Prepare the steamer","content":"Pour water below the rack in a large pot; the water must not touch the tamales."},{"title":"Load the steamer","content":"Set the tamales on the rack, closures facing up, with room for steam to circulate."},{"title":"Steam","content":"Steam with the lid on for 3 hours from a steady flow of steam; keep the water boiling and top up with boiling water down the side as needed.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-33.webp","image_alt":"Steam"},{"title":"Check doneness","content":"Probe the center and chicken in a tamal: both must reach at least 74 °C and the dough must be set; if needed, steam for further 15-minute intervals."},{"title":"Rest","content":"Leave the parcels outside the pot for 15 minutes."},{"title":"Remove the string","content":"Remove the kitchen string from each parcel."},{"title":"Unwrap","content":"Carefully open the leaves, avoiding escaping steam."},{"title":"Serve","content":"Serve one hot tamal per person; do not eat the leaf.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","image_alt":"Colombian Tamales from Tolima"}],"notes":"<p>Choose plain precooked white corn flour, often sold as masarepa, rather than cornstarch or masa harina for tortillas. The parcooked rice keeps its texture in the dough. Thaw frozen banana leaves before starting. Use food-safe kitchen string. Water for boiling eggs, softening leaves and steaming is additional to the measured stock. A two-tier steamer fits 8 tamales without crowding. Refrigerate leftovers in shallow containers within 2 hours; keep for 3–4 days or freeze for up to 2 months. Reheat by steaming until the center reaches 74 °C.</p>","author":"Néstor Bastidas","category":"Main dishes","cuisine":"Colombian","difficulty":"Intermediate","servings":8,"public_path":"/en/receta/colombian-tamales-tolima","prep_time_minutes":90,"cook_time_minutes":225,"marinate_time_minutes":720,"rest_time_minutes":15,"total_time_minutes":1050,"nutrition":{"calories":621.3,"protein_g":41.5,"carbs_g":75.6,"fat_g":16.6,"serving_size":"1 tamal (1 of 8)","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"Sum of raw-ingredient nutrients using USDA profiles, divided by the servings; juice is approximated as 1 g per ml.","note":"Estimate for 1 of 8 tamales, without sides. Uses lean pork and generic white corn flour as a proxy for precooked flour. Excludes unsalted stock and 3 g annatto; flour brand and stock may change the values. The leaves are not eaten."},"excerpt":"These generous tamales from Tolima combine corn dough, rice and peas with pork, chicken, egg, potato and carrot. Banana leaves form round parcels that cook gently in steam.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","course":"Main dishes","keywords":["Colombian Tamales from Tolima"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/ingredientes.webp","alt":"Colombian Tamales from Tolima"}]},{"language":"de","slug":"kolumbianische-tamales-tolima","title":"Kolumbianische Tamales nach Tolima-Art","seo":{"title":"Kolumbianische Tamales nach Tolima-Art","description":"Kolumbianische Tamales aus Tolima: Maisteig mit Reis, Schwein, Hähnchen, Ei und Gemüse. In Bananenblätter gewickelt und schonend im Dampf gegart.","faq":[{"q":"Geht frisch gemahlener Mais?","a":"Ja, allerdings sind Einweichen und Garen dann anders. Mengen und Zeiten gelten hier für vorgekochtes weißes Maismehl."},{"q":"Warum ist die Masse weich?","a":"Eventuell fehlen Garzeit oder Ruhezeit. Wasserstand prüfen, jeweils 15 Minuten weiterdämpfen und die Päckchen vor dem Öffnen ruhen lassen."},{"q":"Kann ich die Päckchen vorbereiten?","a":"Ja. Sofort bei höchstens 4 °C kühlen und innerhalb von 24 Stunden nach dem Marinieren garen. Die 3 Stunden zählen ab gleichmäßigem Dampfaustritt."}],"image_alt":"Kolumbianische Tamales nach Tolima-Art","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-16x9.webp"],"additional_time_minutes":735},"summary":"Diese kräftigen Tamales aus Tolima verbinden Maisteig, Reis und Erbsen mit Schweinefleisch, Hähnchen, Ei, Kartoffeln und Möhren. Die runden Bananenblattpäckchen garen langsam im Dampf.","ingredients":[{"amount":"350","unit":"g","name":"vorgekochtes weißes Maismehl, ohne Salz und Zucker"},{"amount":"250","unit":"g","name":"weißer Reis, ungekocht"},{"amount":"600","unit":"g","name":"magere Schweinekeule ohne Knochen"},{"amount":"600","unit":"g","name":"Hähnchenoberkeulen ohne Haut und Knochen"},{"amount":"4","unit":"Stück","name":"große Eier, etwa 200 g ohne Schale"},{"amount":"400","unit":"g","name":"geschälte Kartoffeln"},{"amount":"200","unit":"g","name":"geschälte Möhren"},{"amount":"160","unit":"g","name":"tiefgekühlte grüne Erbsen"},{"amount":"200","unit":"g","name":"Frühlingszwiebeln"},{"amount":"20","unit":"g","name":"geschälter Knoblauch"},{"amount":"40","unit":"g","name":"Pflanzenöl"},{"amount":"3","unit":"g","name":"reines Annattopulver"},{"amount":"4","unit":"g","name":"gemahlener Kreuzkümmel"},{"amount":"16","unit":"g","name":"Salz"},{"amount":"1","unit":"g","name":"gemahlener schwarzer Pfeffer"},{"amount":"1000","unit":"ml","name":"kalte Hühnerbrühe ohne Salz"},{"amount":"450","unit":"ml","name":"Wasser für den Reis"},{"amount":"100","unit":"ml","name":"Wasser für die Marinade"},{"amount":"16","unit":"Stück","name":"Bananenblattstücke zum Kochen, etwa 40 × 40 cm"}],"steps":[{"title":"Schweinefleisch schneiden","content":"Die 600 g Schweinefleisch in 8 gleich große Stücke schneiden."},{"title":"Hähnchen schneiden","content":"Die 600 g Hähnchenfleisch in 8 gleich große Stücke schneiden."},{"title":"Zwiebeln hacken","content":"Die 200 g Frühlingszwiebeln fein hacken."},{"title":"Knoblauch hacken","content":"Die 20 g Knoblauch fein hacken."},{"title":"Marinade mischen","content":"100 g Frühlingszwiebeln, den gesamten Knoblauch, 2 g Kreuzkümmel, 10 g Salz, 1 g Pfeffer und 100 ml Wasser verrühren."},{"title":"Fleisch marinieren","content":"Schweinefleisch und Hähnchen in einem verschließbaren Behälter mit der gesamten Marinade überziehen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-06.webp","image_alt":"Fleisch marinieren"},{"title":"Kühl stellen","content":"Das Fleisch zugedeckt 12 Stunden bei höchstens 4 °C kühlen."},{"title":"Eier kochen","content":"Die 4 Eier in leicht kochendem Wasser 10 Minuten garen."},{"title":"Eier abkühlen","content":"Die Eier 5 Minuten in kaltes Wasser legen."},{"title":"Eier schälen","content":"Die Schalen der Eier entfernen."},{"title":"Eier halbieren","content":"Jedes Ei halbieren, sodass 8 Hälften entstehen."},{"title":"Kartoffeln schneiden","content":"Die 400 g Kartoffeln in 5 mm dicke Scheiben schneiden."},{"title":"Möhren schneiden","content":"Die 200 g Möhren in 3 mm dicke Scheiben schneiden."},{"title":"Reis vorgaren","content":"Die 250 g Reis mit 450 ml Wasser zugedeckt bei kleiner Hitze ab dem Aufkochen 12 Minuten garen; die Körner sollen noch etwas fest sein.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-14.webp","image_alt":"Reis vorgaren"},{"title":"Zwiebeln dünsten","content":"Die übrigen 100 g Frühlingszwiebeln im 40 g Öl bei mittlerer Hitze 5 Minuten dünsten."},{"title":"Würzen","content":"3 g Annatto, 2 g Kreuzkümmel und 6 g Salz 30 Sekunden unter die Zwiebeln rühren."},{"title":"Maismehl anrühren","content":"Die 350 g Maismehl mit den 1000 ml kalter Brühe glatt rühren."},{"title":"Teig andicken","content":"Die Maismischung bei mittlerer bis kleiner Hitze 5–8 Minuten unter Rühren zu einer dicken, streichfähigen Masse garen."},{"title":"Masse vermengen","content":"Maismasse, Reis, 160 g Erbsen und die gesamte Zwiebelmischung vermengen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-19.webp","image_alt":"Masse vermengen"},{"title":"Blätter waschen","content":"Die 16 Bananenblattstücke mit Trinkwasser waschen."},{"title":"Blätter erweichen","content":"Die Blätter 2 Minuten in heißes Wasser tauchen, bis sie biegsam sind."},{"title":"Blätter trocknen","content":"Die Blätter mit einem sauberen Tuch trocken tupfen."},{"title":"Unterlagen auslegen","content":"Für jeden Tamal 2 Blätter über Kreuz legen, die glattere Seite nach oben."},{"title":"Teig verteilen","content":"Die Hälfte der Masse auf die 8 Blattunterlagen verteilen; die Ränder frei lassen."},{"title":"Fleisch auflegen","content":"Je 1 Stück Schweinefleisch und Hähnchen auflegen; auch die Marinade gleichmäßig verteilen."},{"title":"Gemüse auflegen","content":"Kartoffeln und Möhren auf die 8 Tamales verteilen."},{"title":"Eier auflegen","content":"Auf jeden Tamal eine Eihälfte legen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-27.webp","image_alt":"Eier auflegen"},{"title":"Füllung bedecken","content":"Die übrige Masse über den Füllungen verteilen."},{"title":"Blätter schließen","content":"Die Ränder nach oben zusammennehmen und zu geschlossenen runden Päckchen formen."},{"title":"Päckchen binden","content":"Jedes Päckchen mit Küchengarn sichern, ohne den Teig zusammenzudrücken.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-30.webp","image_alt":"Päckchen binden"},{"title":"Dämpftopf vorbereiten","content":"Wasser unter den Einsatz eines großen Topfes geben; es darf die Tamales nicht berühren."},{"title":"Tamales einsetzen","content":"Die Tamales mit dem Verschluss nach oben auf den Einsatz stellen; Platz für den Dampf lassen."},{"title":"Dämpfen","content":"Ab gleichmäßigem Dampfaustritt zugedeckt 3 Stunden dämpfen; das Wasser kochend halten und bei Bedarf seitlich kochendes Wasser nachfüllen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-33.webp","image_alt":"Dämpfen"},{"title":"Gargrad prüfen","content":"Mitte und Hähnchen eines Tamals messen: Beide müssen mindestens 74 °C erreichen und die Masse muss fest sein; bei Bedarf jeweils 15 Minuten weiterdämpfen."},{"title":"Ruhen lassen","content":"Die Päckchen außerhalb des Topfes 15 Minuten ruhen lassen."},{"title":"Garn entfernen","content":"Das Küchengarn von jedem Päckchen entfernen."},{"title":"Auspacken","content":"Die Blätter vorsichtig öffnen; auf heißen Dampf achten."},{"title":"Servieren","content":"Pro Person einen heißen Tamal servieren; das Blatt wird nicht gegessen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","image_alt":"Kolumbianische Tamales nach Tolima-Art"}],"notes":"<p>Vorgekochtes weißes Maismehl, auch Masarepa genannt, verwenden; Speisestärke und Tortilla-Maismehl sind kein direkter Ersatz. Der Reis bleibt durch das Vorgaren im Teig körnig. Tiefgekühlte Blätter vorher auftauen. Lebensmittelechtes Küchengarn verwenden. Wasser für Eier, Blätter und Dämpftopf kommt zusätzlich zur abgemessenen Brühe hinzu. Ein Dämpfer mit zwei Ebenen bietet Platz für 8 Päckchen. Reste innerhalb von 2 Stunden in flachen Behältern kühlen; 3–4 Tage im Kühlschrank oder bis zu 2 Monate tiefgekühlt lagern. Beim Aufwärmen im Dampf müssen im Kern 74 °C erreicht werden.</p>","author":"Néstor Bastidas","category":"Hauptgerichte","cuisine":"Kolumbianisch","difficulty":"Mittel","servings":8,"public_path":"/de/receta/kolumbianische-tamales-tolima","prep_time_minutes":90,"cook_time_minutes":225,"marinate_time_minutes":720,"rest_time_minutes":15,"total_time_minutes":1050,"nutrition":{"calories":621.3,"protein_g":41.5,"carbs_g":75.6,"fat_g":16.6,"serving_size":"1 Tamal (1 von 8)","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"Nährstoffe der rohen Zutaten nach USDA-Profilen summiert und durch die Portionenzahl geteilt; Saft mit 1 g je ml angenähert.","note":"Schätzung für 1 von 8 Tamales ohne Beilagen. Mageres Schweinefleisch und allgemeines weißes Maismehl dienen als Grundlage; das Mehl ersetzt rechnerisch vorgekochtes Mehl. Brühe ohne Salz und 3 g Annatto sind nicht enthalten; Mehlmarke und Brühe verändern die Werte. Blätter werden nicht gegessen."},"excerpt":"Diese kräftigen Tamales aus Tolima verbinden Maisteig, Reis und Erbsen mit Schweinefleisch, Hähnchen, Ei, Kartoffeln und Möhren. Die runden Bananenblattpäckchen garen langsam im Dampf.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","course":"Hauptgerichte","keywords":["Kolumbianische Tamales nach Tolima-Art"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/ingredientes.webp","alt":"Kolumbianische Tamales nach Tolima-Art"}]},{"language":"fr","slug":"tamales-colombiens-tolima","title":"Tamales colombiens du Tolima","seo":{"title":"Tamales colombiens du Tolima","description":"Préparez les tamales du Tolima : pâte de maïs et riz, porc, poulet, œuf et légumes, enveloppés de feuilles de bananier puis cuits à la vapeur.","faq":[{"q":"Peut-on utiliser du maïs fraîchement moulu ?","a":"Oui, mais le trempage et la cuisson seront différents. Les quantités et les temps indiqués correspondent à une farine de maïs blanc précuite."},{"q":"Pourquoi la pâte reste-t-elle molle ?","a":"Elle peut manquer de cuisson ou de repos. Vérifiez le niveau d’eau, poursuivez par tranches de 15 minutes et laissez reposer avant d’ouvrir."},{"q":"Peut-on les préparer la veille ?","a":"Oui. Réfrigérez aussitôt à 4 °C maximum et cuisez dans les 24 heures suivant la mise en marinade. Comptez les 3 heures dès que la vapeur est régulière."}],"image_alt":"Tamales colombiens du Tolima","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-16x9.webp"],"additional_time_minutes":735},"summary":"Les tamales du Tolima associent une pâte de maïs, du riz et des petits pois à du porc, du poulet, de l’œuf, de la pomme de terre et de la carotte. Les feuilles de bananier forment des ballotins ronds à cuire à la vapeur.","ingredients":[{"amount":"350","unit":"g","name":"farine de maïs blanc précuite, sans sel ni sucre"},{"amount":"250","unit":"g","name":"riz blanc cru"},{"amount":"600","unit":"g","name":"cuisse de porc maigre désossée"},{"amount":"600","unit":"g","name":"hauts de cuisse de poulet désossés et sans peau"},{"amount":"4","unit":"pièce","name":"gros œufs, environ 200 g sans coquille"},{"amount":"400","unit":"g","name":"pommes de terre épluchées"},{"amount":"200","unit":"g","name":"carottes épluchées"},{"amount":"160","unit":"g","name":"petits pois surgelés"},{"amount":"200","unit":"g","name":"oignons nouveaux"},{"amount":"20","unit":"g","name":"ail épluché"},{"amount":"40","unit":"g","name":"huile végétale"},{"amount":"3","unit":"g","name":"rocou pur en poudre"},{"amount":"4","unit":"g","name":"cumin moulu"},{"amount":"16","unit":"g","name":"sel"},{"amount":"1","unit":"g","name":"poivre noir moulu"},{"amount":"1000","unit":"ml","name":"bouillon de poulet froid sans sel"},{"amount":"450","unit":"ml","name":"eau pour le riz"},{"amount":"100","unit":"ml","name":"eau pour la marinade"},{"amount":"16","unit":"pièce","name":"feuilles de bananier alimentaires, morceaux de 40 × 40 cm environ"}],"steps":[{"title":"Coupez le porc","content":"Coupez les 600 g de porc en 8 morceaux égaux."},{"title":"Coupez le poulet","content":"Coupez les 600 g de poulet en 8 morceaux égaux."},{"title":"Hachez les oignons","content":"Hachez finement les 200 g d’oignons nouveaux."},{"title":"Hachez l’ail","content":"Hachez finement les 20 g d’ail."},{"title":"Préparez la marinade","content":"Mélangez 100 g d’oignons, tout l’ail, 2 g de cumin, 10 g de sel, 1 g de poivre et 100 ml d’eau."},{"title":"Enrobez les viandes","content":"Enrobez le porc et le poulet de toute la marinade dans une boîte avec couvercle.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-06.webp","image_alt":"Enrobez les viandes"},{"title":"Réfrigérez","content":"Gardez les viandes couvertes 12 heures au réfrigérateur à 4 °C maximum."},{"title":"Cuisez les œufs","content":"Faites cuire les 4 œufs dans de l’eau frémissante pendant 10 minutes."},{"title":"Refroidissez les œufs","content":"Plongez les œufs dans de l’eau froide pendant 5 minutes."},{"title":"Écalez les œufs","content":"Retirez les coquilles."},{"title":"Partagez les œufs","content":"Coupez chaque œuf en deux pour obtenir 8 moitiés."},{"title":"Coupez les pommes de terre","content":"Coupez les 400 g de pommes de terre en rondelles de 5 mm."},{"title":"Coupez les carottes","content":"Coupez les 200 g de carottes en rondelles de 3 mm."},{"title":"Précuisez le riz","content":"Faites cuire les 250 g de riz avec 450 ml d’eau, à couvert et à feu doux, 12 minutes à partir de l’ébullition ; il doit rester légèrement ferme.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-14.webp","image_alt":"Précuisez le riz"},{"title":"Faites revenir les oignons","content":"Faites revenir les 100 g d’oignons restants dans les 40 g d’huile à feu moyen pendant 5 minutes."},{"title":"Assaisonnez","content":"Incorporez 3 g de rocou, 2 g de cumin et 6 g de sel aux oignons pendant 30 secondes."},{"title":"Délayez la farine","content":"Mélangez les 350 g de farine de maïs aux 1000 ml de bouillon froid jusqu’à disparition des grumeaux."},{"title":"Épaississez la pâte","content":"Faites cuire à feu moyen-doux 5–8 minutes en remuant, jusqu’à obtenir une pâte épaisse mais facile à étaler."},{"title":"Assemblez la pâte","content":"Mélangez la pâte de maïs, le riz, les 160 g de petits pois et toute la préparation aux oignons.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-19.webp","image_alt":"Assemblez la pâte"},{"title":"Lavez les feuilles","content":"Lavez les 16 feuilles de bananier à l’eau potable."},{"title":"Assouplissez les feuilles","content":"Plongez les feuilles dans de l’eau chaude pendant 2 minutes, jusqu’à ce qu’elles soient souples."},{"title":"Séchez les feuilles","content":"Séchez les feuilles avec un torchon propre."},{"title":"Disposez les feuilles","content":"Croisez 2 feuilles par tamal, face la plus lisse vers le haut."},{"title":"Répartissez la pâte","content":"Répartissez la moitié de la pâte sur les 8 bases, en laissant les bords libres."},{"title":"Ajoutez les viandes","content":"Déposez 1 morceau de porc et 1 morceau de poulet par tamal, en répartissant aussi la marinade."},{"title":"Ajoutez les légumes","content":"Répartissez les pommes de terre et les carottes entre les 8 tamales."},{"title":"Ajoutez l’œuf","content":"Déposez une moitié d’œuf dans chaque tamal.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-27.webp","image_alt":"Ajoutez l’œuf"},{"title":"Recouvrez la garniture","content":"Répartissez le reste de pâte sur les garnitures."},{"title":"Fermez les feuilles","content":"Ramenez les bords vers le haut pour former des ballotins ronds bien fermés."},{"title":"Ficelez les tamales","content":"Attachez chaque ballotin avec de la ficelle de cuisine sans comprimer la pâte.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-30.webp","image_alt":"Ficelez les tamales"},{"title":"Préparez le cuiseur","content":"Versez de l’eau sous le panier d’une grande marmite, sans qu’elle puisse toucher les tamales."},{"title":"Placez les ballotins","content":"Posez les tamales dans le panier, fermeture vers le haut, en laissant circuler la vapeur."},{"title":"Cuisez à la vapeur","content":"Cuisez à couvert 3 heures dès que la vapeur est régulière ; maintenez l’ébullition et complétez au besoin avec de l’eau bouillante versée sur le côté.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-33.webp","image_alt":"Cuisez à la vapeur"},{"title":"Vérifiez la cuisson","content":"Mesurez le centre et le poulet d’un tamal : ils doivent atteindre au moins 74 °C et la pâte doit être prise ; sinon, poursuivez par tranches de 15 minutes."},{"title":"Laissez reposer","content":"Laissez les ballotins hors de la marmite pendant 15 minutes."},{"title":"Retirez la ficelle","content":"Retirez la ficelle de chaque ballotin."},{"title":"Ouvrez les tamales","content":"Ouvrez les feuilles avec précaution, en évitant la vapeur."},{"title":"Servez","content":"Servez un tamal chaud par personne ; la feuille ne se mange pas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","image_alt":"Tamales colombiens du Tolima"}],"notes":"<p>Choisissez de la farine de maïs blanc précuite, appelée masarepa, et non de la fécule de maïs ou de la farine à tortillas. Le riz précuit conserve ses grains dans la pâte. Décongelez les feuilles avant de commencer. Utilisez une ficelle alimentaire. L’eau pour les œufs, les feuilles et la cuisson vapeur s’ajoute au bouillon mesuré. Un cuiseur à deux étages permet de placer les 8 tamales sans les serrer. Réfrigérez les restes dans des récipients peu profonds avant 2 heures ; gardez-les 3–4 jours ou congelez-les jusqu’à 2 mois. Réchauffez à la vapeur jusqu’à 74 °C à cœur.</p>","author":"Néstor Bastidas","category":"Plats principaux","cuisine":"Colombienne","difficulty":"Intermédiaire","servings":8,"public_path":"/fr/receta/tamales-colombiens-tolima","prep_time_minutes":90,"cook_time_minutes":225,"marinate_time_minutes":720,"rest_time_minutes":15,"total_time_minutes":1050,"nutrition":{"calories":621.3,"protein_g":41.5,"carbs_g":75.6,"fat_g":16.6,"serving_size":"1 tamal (1 sur 8)","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"Somme des nutriments des ingrédients crus selon les profils USDA, divisée par le nombre de portions ; jus estimé à 1 g par ml.","note":"Estimation pour 1 des 8 tamales, sans accompagnement. Calcul avec porc maigre et farine de maïs blanc générique comme approximation de la farine précuite. Bouillon sans sel et 3 g de rocou exclus ; les valeurs varient selon la farine et le bouillon. Les feuilles ne se mangent pas."},"excerpt":"Les tamales du Tolima associent une pâte de maïs, du riz et des petits pois à du porc, du poulet, de l’œuf, de la pomme de terre et de la carotte. Les feuilles de bananier forment des ballotins ronds à cuire à la vapeur.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","course":"Plats principaux","keywords":["Tamales colombiens du Tolima"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/ingredientes.webp","alt":"Tamales colombiens du Tolima"}]},{"language":"it","slug":"tamales-colombiani-tolima","title":"Tamales colombiani del Tolima","seo":{"title":"Tamales colombiani del Tolima","description":"Prepara i tamales del Tolima con impasto di mais e riso, maiale, pollo, uova e verdure, avvolti in foglie di banano e cotti lentamente al vapore.","faq":[{"q":"Posso usare mais appena macinato?","a":"Sì, ma richiede un diverso ammollo e un’altra cottura. Dosi e tempi di questa ricetta si riferiscono a farina di mais bianco precotta."},{"q":"Perché l’impasto è molle?","a":"Potrebbero mancare cottura o riposo. Controlla l’acqua, prosegui per intervalli di 15 minuti e fai riposare i fagotti prima di aprirli."},{"q":"Posso prepararli in anticipo?","a":"Sì. Mettili subito in frigorifero a 4 °C o meno e cuocili entro 24 ore dall’inizio della marinatura. Conta le 3 ore dal vapore costante."}],"image_alt":"Tamales colombiani del Tolima","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-16x9.webp"],"additional_time_minutes":735},"summary":"I tamales del Tolima racchiudono impasto di mais, riso e piselli insieme a maiale, pollo, uova, patate e carote. Le foglie di banano formano fagotti tondi da cuocere lentamente al vapore.","ingredients":[{"amount":"350","unit":"g","name":"farina di mais bianco precotta, senza sale né zucchero"},{"amount":"250","unit":"g","name":"riso bianco crudo"},{"amount":"600","unit":"g","name":"coscia di maiale magra disossata"},{"amount":"600","unit":"g","name":"sovracosce di pollo disossate e senza pelle"},{"amount":"4","unit":"pezzo","name":"uova grandi, circa 200 g senza guscio"},{"amount":"400","unit":"g","name":"patate sbucciate"},{"amount":"200","unit":"g","name":"carote pelate"},{"amount":"160","unit":"g","name":"piselli verdi surgelati"},{"amount":"200","unit":"g","name":"cipollotti"},{"amount":"20","unit":"g","name":"aglio sbucciato"},{"amount":"40","unit":"g","name":"olio vegetale"},{"amount":"3","unit":"g","name":"annatto puro in polvere"},{"amount":"4","unit":"g","name":"cumino macinato"},{"amount":"16","unit":"g","name":"sale"},{"amount":"1","unit":"g","name":"pepe nero macinato"},{"amount":"1000","unit":"ml","name":"brodo di pollo freddo senza sale"},{"amount":"450","unit":"ml","name":"acqua per il riso"},{"amount":"100","unit":"ml","name":"acqua per la marinata"},{"amount":"16","unit":"pezzo","name":"fogli di banano per uso alimentare, circa 40 × 40 cm"}],"steps":[{"title":"Taglia il maiale","content":"Taglia i 600 g di maiale in 8 pezzi uguali."},{"title":"Taglia il pollo","content":"Taglia i 600 g di pollo in 8 pezzi uguali."},{"title":"Trita i cipollotti","content":"Trita finemente i 200 g di cipollotti."},{"title":"Trita l’aglio","content":"Trita finemente i 20 g di aglio."},{"title":"Prepara la marinata","content":"Mescola 100 g di cipollotti, tutto l’aglio, 2 g di cumino, 10 g di sale, 1 g di pepe e 100 ml d’acqua."},{"title":"Condisci le carni","content":"Rivesti maiale e pollo con tutta la marinata in un contenitore con coperchio.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-06.webp","image_alt":"Condisci le carni"},{"title":"Metti in frigorifero","content":"Lascia le carni coperte in frigorifero a 4 °C o meno per 12 ore."},{"title":"Lessa le uova","content":"Cuoci le 4 uova in acqua a leggero bollore per 10 minuti."},{"title":"Raffredda le uova","content":"Immergi le uova in acqua fredda per 5 minuti."},{"title":"Sguscia le uova","content":"Elimina i gusci delle uova."},{"title":"Dividi le uova","content":"Taglia ogni uovo a metà, ottenendo 8 metà."},{"title":"Taglia le patate","content":"Taglia i 400 g di patate a fette di 5 mm."},{"title":"Taglia le carote","content":"Taglia i 200 g di carote a rondelle di 3 mm."},{"title":"Precuoci il riso","content":"Cuoci i 250 g di riso con 450 ml d’acqua, coperto e a fuoco basso, per 12 minuti dal bollore; deve restare leggermente al dente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-14.webp","image_alt":"Precuoci il riso"},{"title":"Rosola i cipollotti","content":"Cuoci i 100 g di cipollotti rimasti nei 40 g d’olio a fuoco medio per 5 minuti."},{"title":"Aggiungi le spezie","content":"Incorpora ai cipollotti 3 g di annatto, 2 g di cumino e 6 g di sale per 30 secondi."},{"title":"Stempera la farina","content":"Mescola i 350 g di farina di mais con i 1000 ml di brodo freddo fino a eliminare i grumi."},{"title":"Addensa l’impasto","content":"Cuoci a fuoco medio-basso per 5–8 minuti, mescolando fino a ottenere un composto denso ma spalmabile."},{"title":"Amalgama l’impasto","content":"Mescola il composto di mais con il riso, i 160 g di piselli e tutto il soffritto.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-19.webp","image_alt":"Amalgama l’impasto"},{"title":"Lava le foglie","content":"Lava le 16 foglie di banano con acqua potabile."},{"title":"Ammorbidisci le foglie","content":"Immergi le foglie in acqua calda per 2 minuti, finché diventano flessibili."},{"title":"Asciuga le foglie","content":"Asciuga le foglie con un canovaccio pulito."},{"title":"Disponi le basi","content":"Incrocia 2 foglie per ogni tamal, con il lato più liscio verso l’alto."},{"title":"Distribuisci l’impasto","content":"Dividi metà impasto sulle 8 basi, lasciando liberi i bordi."},{"title":"Aggiungi le carni","content":"Disponi 1 pezzo di maiale e 1 di pollo per tamal, distribuendo anche la marinata."},{"title":"Aggiungi le verdure","content":"Distribuisci patate e carote negli 8 tamales."},{"title":"Aggiungi l’uovo","content":"Metti mezzo uovo in ogni tamal.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-27.webp","image_alt":"Aggiungi l’uovo"},{"title":"Copri il ripieno","content":"Distribuisci l’impasto restante sui ripieni."},{"title":"Chiudi le foglie","content":"Raccogli i bordi verso l’alto formando fagotti tondi ben chiusi."},{"title":"Lega i tamales","content":"Fissa ogni fagotto con spago da cucina senza comprimere l’impasto.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-30.webp","image_alt":"Lega i tamales"},{"title":"Prepara la vaporiera","content":"Versa acqua sotto il cestello di una pentola capiente, senza che raggiunga i tamales."},{"title":"Sistema i fagotti","content":"Disponi i tamales sul cestello con la chiusura in alto e spazio per il vapore."},{"title":"Cuoci al vapore","content":"Cuoci con il coperchio per 3 ore dall’emissione costante di vapore; mantieni il bollore e rabbocca dal lato con acqua bollente quando serve.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-33.webp","image_alt":"Cuoci al vapore"},{"title":"Controlla la cottura","content":"Misura il centro e il pollo di un tamal: entrambi devono raggiungere almeno 74 °C e l’impasto deve essere sodo; altrimenti continua per intervalli di 15 minuti."},{"title":"Lascia riposare","content":"Lascia i fagotti fuori dalla pentola per 15 minuti."},{"title":"Togli lo spago","content":"Rimuovi lo spago da ogni fagotto."},{"title":"Apri i tamales","content":"Apri le foglie con cautela, evitando il vapore."},{"title":"Servi","content":"Servi un tamal caldo a persona; la foglia non si mangia.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","image_alt":"Tamales colombiani del Tolima"}],"notes":"<p>Usa farina di mais bianco precotta, detta masarepa, non amido di mais, farina per polenta o farina per tortillas. Il riso precotto mantiene i chicchi nell’impasto. Scongela le foglie prima di iniziare. Usa spago alimentare. L’acqua per uova, foglie e vaporiera è aggiuntiva rispetto al brodo misurato. Una vaporiera a due piani ospita gli 8 tamales senza comprimerli. Riponi gli avanzi in frigorifero entro 2 ore in contenitori bassi; consumali entro 3–4 giorni o congelali fino a 2 mesi. Riscalda al vapore fino a 74 °C al cuore.</p>","author":"Néstor Bastidas","category":"Secondi piatti","cuisine":"Colombiana","difficulty":"Media","servings":8,"public_path":"/it/receta/tamales-colombiani-tolima","prep_time_minutes":90,"cook_time_minutes":225,"marinate_time_minutes":720,"rest_time_minutes":15,"total_time_minutes":1050,"nutrition":{"calories":621.3,"protein_g":41.5,"carbs_g":75.6,"fat_g":16.6,"serving_size":"1 tamal (1 di 8)","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"Somma dei nutrienti degli ingredienti crudi secondo profili USDA, divisa per le porzioni; i succhi sono approssimati a 1 g per ml.","note":"Stima per 1 degli 8 tamales, senza contorni. Usa maiale magro e farina di mais bianco generica come approssimazione di quella precotta. Esclude brodo senza sale e 3 g di annatto; marca della farina e brodo possono cambiare i valori. Le foglie non si mangiano."},"excerpt":"I tamales del Tolima racchiudono impasto di mais, riso e piselli insieme a maiale, pollo, uova, patate e carote. Le foglie di banano formano fagotti tondi da cuocere lentamente al vapore.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","course":"Secondi piatti","keywords":["Tamales colombiani del Tolima"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/ingredientes.webp","alt":"Tamales colombiani del Tolima"}]},{"language":"ja","slug":"colombia-tamal-tolima","title":"コロンビア・トリマ地方のタマル","seo":{"title":"コロンビア・トリマ地方のタマル","description":"コロンビアのトリマ地方で親しまれるタマルを家庭で。米ととうもろこしの生地に、豚肉、鶏肉、卵、グリーンピース、にんじん、じゃがいもを包みます。バナナの葉の下処理から包み方、蒸し時間、中心温度の確認まで、ひとつずつ分かりやすく紹介する８個分のレシピです。","faq":[{"q":"生のとうもろこしをひいて使えますか？","a":"使えますが、浸水と加熱の手順が変わります。この分量と時間は加熱済みの白とうもろこし粉用です。"},{"q":"生地が柔らかいのはなぜですか？","a":"蒸し時間や休ませる時間が不足している場合があります。水量を確認し、15分ずつ追加で蒸してから、包みを休ませてください。"},{"q":"前日に包んでもよいですか？","a":"包んだらすぐ4 °C以下で冷蔵し、肉を漬け始めてから24時間以内に蒸してください。3時間は蒸気が安定してから数えます。"}],"image_alt":"コロンビア・トリマ地方のタマル","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-16x9.webp"],"additional_time_minutes":735},"summary":"トリマ地方のタマルは、米ととうもろこしの生地に肉や野菜をたっぷり包む料理。豚肉、鶏肉、卵、じゃがいも、にんじんを入れ、バナナの葉で丸く包んでじっくり蒸します。","ingredients":[{"amount":"350","unit":"g","name":"加熱済みの白とうもろこし粉（無塩・無糖のマサレパ）"},{"amount":"250","unit":"g","name":"白米（乾燥重量）"},{"amount":"600","unit":"g","name":"豚もも赤身肉（骨なし）"},{"amount":"600","unit":"g","name":"鶏もも肉（骨・皮なし）"},{"amount":"4","unit":"個","name":"大きめの卵（殻を除いて約200 g）"},{"amount":"400","unit":"g","name":"じゃがいも（皮をむいたもの）"},{"amount":"200","unit":"g","name":"にんじん（皮をむいたもの）"},{"amount":"160","unit":"g","name":"冷凍グリーンピース"},{"amount":"200","unit":"g","name":"青ねぎ"},{"amount":"20","unit":"g","name":"にんにく（皮をむいたもの）"},{"amount":"40","unit":"g","name":"植物油"},{"amount":"3","unit":"g","name":"アナトー粉末（単一原料）"},{"amount":"4","unit":"g","name":"クミンパウダー"},{"amount":"16","unit":"g","name":"塩"},{"amount":"1","unit":"g","name":"粗びき黒こしょう"},{"amount":"1000","unit":"ml","name":"無塩チキンスープ（冷たいもの）"},{"amount":"450","unit":"ml","name":"炊飯用の水"},{"amount":"100","unit":"ml","name":"漬けだれ用の水"},{"amount":"16","unit":"個","name":"調理用バナナの葉（約40 × 40 cm）"}],"steps":[{"title":"豚肉を切る","content":"豚肉600 gを同じ大きさの8切れに切ります。"},{"title":"鶏肉を切る","content":"鶏肉600 gを同じ大きさの8切れに切ります。"},{"title":"ねぎを刻む","content":"青ねぎ200 gをみじん切りにします。"},{"title":"にんにくを刻む","content":"にんにく20 gをみじん切りにします。"},{"title":"たれを混ぜる","content":"青ねぎ100 g、にんにく全量、クミン2 g、塩10 g、黒こしょう1 g、水100 mlを混ぜます。"},{"title":"肉にたれをからめる","content":"ふた付き容器で豚肉と鶏肉に漬けだれを全量からめます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-06.webp","image_alt":"肉にたれをからめる"},{"title":"冷蔵する","content":"ふたをして4 °C以下の冷蔵庫に12時間置きます。"},{"title":"卵をゆでる","content":"卵4個を静かに沸く湯で10分ゆでます。"},{"title":"卵を冷やす","content":"卵を冷水に5分浸します。"},{"title":"殻をむく","content":"卵の殻を取り除きます。"},{"title":"卵を半分に切る","content":"卵をそれぞれ半分に切り、8切れにします。"},{"title":"じゃがいもを切る","content":"じゃがいも400 gを厚さ5 mmに切ります。"},{"title":"にんじんを切る","content":"にんじん200 gを厚さ3 mmの輪切りにします。"},{"title":"米を下ゆでする","content":"米250 gに水450 mlを加え、ふたをして沸騰後弱火で12分炊きます。少し芯が残る程度にします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-14.webp","image_alt":"米を下ゆでする"},{"title":"ねぎを炒める","content":"残りの青ねぎ100 gを油40 gで中火で5分炒めます。"},{"title":"香辛料を加える","content":"炒めたねぎにアナトー3 g、クミン2 g、塩6 gを混ぜ、30秒加熱します。"},{"title":"粉を溶く","content":"とうもろこし粉350 gと冷たいスープ1000 mlを、だまがなくなるまで混ぜます。"},{"title":"生地を加熱する","content":"中弱火で5〜8分混ぜながら加熱し、広げられる程度の濃いペーストにします。"},{"title":"生地を合わせる","content":"とうもろこしの生地、米、グリーンピース160 g、炒めたねぎの全量を混ぜます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-19.webp","image_alt":"生地を合わせる"},{"title":"葉を洗う","content":"バナナの葉16枚を飲用水で洗います。"},{"title":"葉を柔らかくする","content":"葉を熱い湯に2分浸し、折りやすくします。"},{"title":"葉を拭く","content":"清潔な布で葉の水気を拭き取ります。"},{"title":"葉を重ねる","content":"1個につき葉2枚を十字に重ね、滑らかな面を上にします。"},{"title":"生地を分ける","content":"生地の半量を8組の葉に分け、周囲を空けます。"},{"title":"肉をのせる","content":"各生地に豚肉と鶏肉を1切れずつのせ、漬けだれも均等に分けます。"},{"title":"野菜をのせる","content":"じゃがいもとにんじんを8個分に分けてのせます。"},{"title":"卵をのせる","content":"1個につき半分に切った卵を1切れのせます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-27.webp","image_alt":"卵をのせる"},{"title":"生地をかぶせる","content":"残りの生地を具の上に均等にのせます。"},{"title":"葉を閉じる","content":"葉の端を上に寄せ、丸い包みにしてしっかり閉じます。"},{"title":"ひもで結ぶ","content":"生地を押しつぶさないよう、調理用たこ糸で包みを固定します。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-30.webp","image_alt":"ひもで結ぶ"},{"title":"蒸し器を用意する","content":"大鍋の蒸し台より下に水を入れます。水がタマルに触れない量にします。"},{"title":"包みを並べる","content":"閉じ目を上にして蒸し台に並べ、蒸気の通り道を空けます。"},{"title":"蒸す","content":"蒸気が安定して上がってから、ふたをして3時間蒸します。沸騰を保ち、必要に応じて鍋の端から熱湯を補います。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-33.webp","image_alt":"蒸す"},{"title":"火通りを確認する","content":"タマルの中心と鶏肉を温度計で測り、両方が74 °C以上で生地が固まっていることを確認します。不足する場合は15分ずつ追加で蒸します。"},{"title":"休ませる","content":"鍋から出した包みを15分休ませます。"},{"title":"ひもを外す","content":"包みのたこ糸を取り除きます。"},{"title":"葉を開く","content":"蒸気に注意して葉を開きます。"},{"title":"盛り付ける","content":"1人につき温かいタマルを1個盛り付けます。葉は食べません。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","image_alt":"コロンビア・トリマ地方のタマル"}],"notes":"<p>粉は加熱済みの白とうもろこし粉「マサレパ」を使います。コーンスターチやトルティーヤ用のマサ粉とは異なります。米は下ゆでし、粒の食感を残します。冷凍の葉は先に解凍してください。ひもは調理用を使います。卵、葉、蒸し器に使う水は、分量のスープとは別に用意します。2段の蒸し器なら8個を詰め込まずに並べられます。残りは2時間以内に浅い容器に入れて冷蔵し、3〜4日で食べ切るか、最長2か月冷凍します。蒸し直すときは中心を74 °Cまで温めます。</p>","author":"Néstor Bastidas","category":"主菜","cuisine":"コロンビア料理","difficulty":"中級","servings":8,"public_path":"/ja/receta/colombia-tamal-tolima","prep_time_minutes":90,"cook_time_minutes":225,"marinate_time_minutes":720,"rest_time_minutes":15,"total_time_minutes":1050,"nutrition":{"calories":621.3,"protein_g":41.5,"carbs_g":75.6,"fat_g":16.6,"serving_size":"タマル1個（全8個）","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"USDAの食品成分値で生の材料の栄養量を合計し、人数で割った推定値です。果汁は1 mlを1 gとして計算しています。","note":"8個のうち1個分、付け合わせなしの推定値です。豚肉は赤身、加熱済みの粉は一般的な白とうもろこし粉の成分で代用しています。無塩スープとアナトー3 gは計算に含めていません。粉の銘柄やスープで数値は変わります。葉は食べません。"},"excerpt":"トリマ地方のタマルは、米ととうもろこしの生地に肉や野菜をたっぷり包む料理。豚肉、鶏肉、卵、じゃがいも、にんじんを入れ、バナナの葉で丸く包んでじっくり蒸します。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","course":"主菜","keywords":["コロンビア・トリマ地方のタマル"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/ingredientes.webp","alt":"コロンビア・トリマ地方のタマル"}]},{"language":"pt","slug":"tamal-colombiano-tolima","title":"Tamal colombiano do Tolima na folha de bananeira","seo":{"title":"Tamal colombiano do Tolima na folha de bananeira","description":"Aprenda a fazer tamal do Tolima com massa de milho e arroz, porco, frango, ovo e legumes, embrulhado em folha de bananeira e cozido no vapor.","faq":[{"q":"Posso usar milho moído na hora?","a":"Sim, mas será preciso mudar o molho e o cozimento. As quantidades e os tempos desta receita são para farinha de milho branco pré-cozida."},{"q":"Por que a massa ficou mole?","a":"Pode faltar cozimento ou descanso. Confira a água da panela, cozinhe por mais intervalos de 15 minutos e deixe as trouxinhas descansar antes de abrir."},{"q":"Posso montar na véspera?","a":"Sim. Leve imediatamente à geladeira a 4 °C ou menos e cozinhe em até 24 horas após começar a marinar as carnes. Conte as 3 horas a partir do vapor contínuo."}],"image_alt":"Tamal colombiano do Tolima na folha de bananeira","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada-16x9.webp"],"additional_time_minutes":735},"summary":"O tamal do Tolima combina massa de milho, arroz e ervilha com carne suína, frango, ovo, batata e cenoura. As folhas de bananeira formam trouxinhas redondas para cozinhar lentamente no vapor.","ingredients":[{"amount":"350","unit":"g","name":"farinha de milho branco pré-cozida, sem sal nem açúcar"},{"amount":"250","unit":"g","name":"arroz branco cru"},{"amount":"600","unit":"g","name":"pernil suíno magro sem osso"},{"amount":"600","unit":"g","name":"sobrecoxa de frango sem pele e sem osso"},{"amount":"4","unit":"unidade","name":"ovos grandes, cerca de 200 g sem casca"},{"amount":"400","unit":"g","name":"batata descascada"},{"amount":"200","unit":"g","name":"cenoura descascada"},{"amount":"160","unit":"g","name":"ervilha verde congelada"},{"amount":"200","unit":"g","name":"cebolinha"},{"amount":"20","unit":"g","name":"alho descascado"},{"amount":"40","unit":"g","name":"óleo vegetal"},{"amount":"3","unit":"g","name":"urucum puro em pó"},{"amount":"4","unit":"g","name":"cominho em pó"},{"amount":"16","unit":"g","name":"sal"},{"amount":"1","unit":"g","name":"pimenta-do-reino moída"},{"amount":"1000","unit":"ml","name":"caldo de frango frio sem sal"},{"amount":"450","unit":"ml","name":"água para o arroz"},{"amount":"100","unit":"ml","name":"água para a marinada"},{"amount":"16","unit":"unidade","name":"folhas de bananeira próprias para culinária, cerca de 40 × 40 cm"}],"steps":[{"title":"Corte o porco","content":"Corte os 600 g de carne suína em 8 pedaços iguais."},{"title":"Corte o frango","content":"Corte os 600 g de frango em 8 pedaços iguais."},{"title":"Pique a cebolinha","content":"Pique finamente os 200 g de cebolinha."},{"title":"Pique o alho","content":"Pique finamente os 20 g de alho."},{"title":"Misture a marinada","content":"Misture 100 g de cebolinha, todo o alho, 2 g de cominho, 10 g de sal, 1 g de pimenta e 100 ml de água."},{"title":"Tempere as carnes","content":"Envolva o porco e o frango em toda a marinada dentro de um recipiente com tampa.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-06.webp","image_alt":"Tempere as carnes"},{"title":"Leve à geladeira","content":"Mantenha as carnes tampadas na geladeira a 4 °C ou menos por 12 horas."},{"title":"Cozinhe os ovos","content":"Cozinhe os 4 ovos em água fervendo suavemente por 10 minutos."},{"title":"Esfrie os ovos","content":"Coloque os ovos em água fria por 5 minutos."},{"title":"Descasque os ovos","content":"Retire as cascas dos ovos."},{"title":"Divida os ovos","content":"Corte cada ovo ao meio para obter 8 metades."},{"title":"Corte a batata","content":"Corte os 400 g de batata em rodelas de 5 mm."},{"title":"Corte a cenoura","content":"Corte os 200 g de cenoura em rodelas de 3 mm."},{"title":"Pré-cozinhe o arroz","content":"Cozinhe os 250 g de arroz com 450 ml de água, tampado e em fogo baixo, por 12 minutos a partir da fervura; os grãos devem ficar um pouco firmes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-14.webp","image_alt":"Pré-cozinhe o arroz"},{"title":"Refogue a cebolinha","content":"Refogue os 100 g restantes de cebolinha nos 40 g de óleo em fogo médio por 5 minutos."},{"title":"Acrescente os temperos","content":"Incorpore 3 g de urucum, 2 g de cominho e 6 g de sal ao refogado por 30 segundos."},{"title":"Misture a farinha","content":"Misture os 350 g de farinha de milho aos 1000 ml de caldo frio até desfazer os grumos."},{"title":"Engrosse a massa","content":"Cozinhe em fogo médio-baixo por 5–8 minutos, mexendo até obter uma massa espessa que possa ser espalhada."},{"title":"Incorpore o arroz","content":"Misture a massa de milho com o arroz, os 160 g de ervilha e todo o refogado.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-19.webp","image_alt":"Incorpore o arroz"},{"title":"Lave as folhas","content":"Lave as 16 folhas de bananeira com água potável."},{"title":"Amoleça as folhas","content":"Mergulhe as folhas em água quente por 2 minutos, até ficarem flexíveis."},{"title":"Seque as folhas","content":"Seque as folhas com um pano limpo."},{"title":"Monte as bases","content":"Cruze 2 folhas por tamal, com o lado mais liso voltado para cima."},{"title":"Distribua a massa","content":"Divida metade da massa entre as 8 bases, deixando as bordas livres."},{"title":"Coloque as carnes","content":"Coloque 1 pedaço de porco e 1 de frango por tamal, distribuindo também a marinada."},{"title":"Coloque os legumes","content":"Distribua a batata e a cenoura entre os 8 tamales."},{"title":"Coloque o ovo","content":"Coloque meio ovo em cada tamal.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-27.webp","image_alt":"Coloque o ovo"},{"title":"Cubra o recheio","content":"Distribua a massa restante sobre os recheios."},{"title":"Feche as folhas","content":"Junte as bordas para cima, formando trouxinhas redondas bem fechadas."},{"title":"Amarre os tamales","content":"Prenda cada trouxinha com barbante culinário sem apertar a massa.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-30.webp","image_alt":"Amarre os tamales"},{"title":"Prepare a panela","content":"Coloque água abaixo do cesto de uma panela grande, sem alcançar os tamales."},{"title":"Acomode as trouxinhas","content":"Disponha os tamales no cesto, com a abertura para cima e espaço para o vapor circular."},{"title":"Cozinhe no vapor","content":"Cozinhe com tampa por 3 horas a partir do vapor contínuo; mantenha a fervura e reponha água fervente pela lateral quando necessário.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/paso-33.webp","image_alt":"Cozinhe no vapor"},{"title":"Verifique o ponto","content":"Meça o centro e o frango de um tamal: ambos devem atingir pelo menos 74 °C e a massa deve estar firme; se necessário, cozinhe por mais intervalos de 15 minutos."},{"title":"Deixe descansar","content":"Deixe as trouxinhas fora da panela por 15 minutos."},{"title":"Retire o barbante","content":"Retire o barbante de cada trouxinha."},{"title":"Abra os tamales","content":"Abra as folhas com cuidado com o vapor."},{"title":"Sirva","content":"Sirva um tamal quente por pessoa; a folha não é comestível.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","image_alt":"Tamal colombiano do Tolima na folha de bananeira"}],"notes":"<p>Use farinha de milho branco pré-cozida, conhecida como masarepa, e não amido, fubá comum ou farinha para tortillas. O arroz parcialmente cozido mantém os grãos na massa. Descongele as folhas antes de começar. Use barbante culinário. A água para ovos, folhas e panela de vapor é adicional ao caldo medido. Uma panela de vapor com dois andares acomoda os 8 tamales sem apertar. Leve as sobras à geladeira em recipientes rasos em até 2 horas; consuma em 3–4 dias ou congele por até 2 meses. Reaqueça no vapor até atingir 74 °C no centro.</p>","author":"Néstor Bastidas","category":"Pratos principais","cuisine":"Colombiana","difficulty":"Intermediária","servings":8,"public_path":"/pt/receta/tamal-colombiano-tolima","prep_time_minutes":90,"cook_time_minutes":225,"marinate_time_minutes":720,"rest_time_minutes":15,"total_time_minutes":1050,"nutrition":{"calories":621.3,"protein_g":41.5,"carbs_g":75.6,"fat_g":16.6,"serving_size":"1 tamal (1 de 8)","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"Soma dos nutrientes dos ingredientes crus com perfis USDA, dividida pelas porções; os sucos são aproximados como 1 g por ml.","note":"Estimativa para 1 dos 8 tamales, sem acompanhamentos. Usa carne suína magra e farinha de milho branco genérica como aproximação da pré-cozida. Não inclui caldo sem sal nem 3 g de urucum; a marca da farinha e o caldo podem alterar os valores. As folhas não são consumidas."},"excerpt":"O tamal do Tolima combina massa de milho, arroz e ervilha com carne suína, frango, ovo, batata e cenoura. As folhas de bananeira formam trouxinhas redondas para cozinhar lentamente no vapor.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/portada.webp","course":"Pratos principais","keywords":["Tamal colombiano do Tolima na folha de bananeira"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/tamal-tolimense/ingredientes.webp","alt":"Tamal colombiano do Tolima na folha de bananeira"}]}]$content$::jsonb;
 aliases jsonb := $aliases$[{"ingredient_id":"1400dab1-731e-4cc3-9e22-90c22f1355c0","alias":"harina de maíz blanco precocida, sin azúcar ni sal"},{"ingredient_id":"33020d85-23df-4c67-b25c-6fff35c1f776","alias":"arroz blanco seco"},{"ingredient_id":"1d2b384c-fed9-4401-94e9-e0c9c58657cd","alias":"carne magra de pierna de cerdo deshuesada"},{"ingredient_id":"f46c6a2b-2535-469e-b8f3-d7bc191073e7","alias":"muslo de pollo deshuesado y sin piel"},{"ingredient_id":"feae0709-81ed-473d-8980-e4f1763b56a4","alias":"huevos grandes, unos 200 g sin cáscara"},{"ingredient_id":"98322e50-1f0c-406c-8681-b5718d3801ee","alias":"papa pelada"},{"ingredient_id":"1edbaa1e-4862-4962-a525-c663bf7e84f0","alias":"zanahoria pelada"},{"ingredient_id":"d9f5dcc1-d08d-453e-aee6-b1017a84f6c3","alias":"arvejas verdes congeladas"},{"ingredient_id":"11295513-26a1-4869-b002-17199082e331","alias":"cebolla larga"},{"ingredient_id":"75746b02-4b4c-4c2d-8751-04d3b2a24f0e","alias":"ajo pelado"},{"ingredient_id":"cfb1e866-27fa-4e97-99ff-1af1527ac2b3","alias":"aceite vegetal"},{"ingredient_id":"11754abb-fd10-4b9d-93b0-f841f4d6ae85","alias":"achiote molido puro"},{"ingredient_id":"74d0a20e-32b8-4ebc-a434-88b566e72f3c","alias":"comino molido"},{"ingredient_id":"adbdba3e-00c5-4a63-9140-6b0ae740d813","alias":"sal"},{"ingredient_id":"2de4d4f2-8bb2-401b-9b88-a29427b8690b","alias":"pimienta negra molida"},{"ingredient_id":"384c1138-47ae-43aa-8f76-fcc26bdcf0ce","alias":"caldo de pollo sin sal, frío"},{"ingredient_id":"6a189b14-0318-498f-9a7d-81fc2592be37","alias":"agua para el arroz"},{"ingredient_id":"6a189b14-0318-498f-9a7d-81fc2592be37","alias":"agua para el adobo"},{"ingredient_id":"4b5dee25-2bc5-470d-ac50-5d8d71c1a0f7","alias":"hojas de plátano de unos 40 × 40 cm, aptas para cocinar"}]$aliases$::jsonb;
 v_source uuid;
 v_group uuid;
 v_alias jsonb;
 v_n integer;
BEGIN
 IF EXISTS (SELECT 1 FROM public.recipes WHERE slug IN (SELECT x->>'slug' FROM jsonb_array_elements(payload) x))
 OR EXISTS (SELECT 1 FROM public.content_pages WHERE public_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x))
 OR EXISTS (SELECT 1 FROM public.content_redirects WHERE source_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x)) THEN
 RAISE EXCEPTION 'A recipe or route already exists; review identity before publication'; END IF;
 FOR v_alias IN SELECT x FROM jsonb_array_elements(aliases) x LOOP
  IF NOT EXISTS (SELECT 1 FROM public.ingredients WHERE id=(v_alias->>'ingredient_id')::uuid AND status='canonical' AND searchable) THEN RAISE EXCEPTION 'Missing canonical ingredient'; END IF;
  IF EXISTS (SELECT 1 FROM public.ingredient_aliases a JOIN public.ingredients i ON i.id=a.ingredient_id WHERE a.normalized_alias=lower(v_alias->>'alias') AND a.ingredient_id<>(v_alias->>'ingredient_id')::uuid AND i.status='canonical') THEN RAISE EXCEPTION 'Ingredient alias collision'; END IF;
  INSERT INTO public.ingredient_aliases (ingredient_id,alias,normalized_alias) VALUES ((v_alias->>'ingredient_id')::uuid,v_alias->>'alias',lower(v_alias->>'alias')) ON CONFLICT (ingredient_id,normalized_alias) DO NOTHING;
 END LOOP;
 INSERT INTO public.recipes (language, slug, title, excerpt, summary, ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url, content_html, notes, difficulty, course, cuisine, keywords, nutrition, seo, public_path, gallery,published,editorial_status)
 SELECT s.language, s.slug, s.title, s.excerpt, s.summary, s.ingredients, s.steps, s.category, s.prep_time_minutes, s.cook_time_minutes, s.total_time_minutes, s.servings, s.image_url, s.content_html, s.notes, s.difficulty, s.course, s.cuisine, s.keywords, s.nutrition, s.seo, s.public_path, s.gallery,false,'draft' FROM jsonb_populate_recordset(NULL::public.recipes,payload) s WHERE s.language='es'
 RETURNING id,recipe_group_id INTO v_source,v_group;
 INSERT INTO public.recipes (recipe_group_id,language, slug, title, excerpt, summary, ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url, content_html, notes, difficulty, course, cuisine, keywords, nutrition, seo, public_path, gallery,published,editorial_status)
 SELECT v_group,s.language, s.slug, s.title, s.excerpt, s.summary, s.ingredients, s.steps, s.category, s.prep_time_minutes, s.cook_time_minutes, s.total_time_minutes, s.servings, s.image_url, s.content_html, s.notes, s.difficulty, s.course, s.cuisine, s.keywords, s.nutrition, s.seo, s.public_path, s.gallery,false,'draft' FROM jsonb_populate_recordset(NULL::public.recipes,payload) s WHERE s.language<>'es';
 IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=v_source)<>19 OR EXISTS (SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=v_source) THEN RAISE EXCEPTION 'Ingredient catalogue mapping incomplete'; END IF;
 UPDATE public.recipes SET published=true,editorial_status='published',ready_at=coalesce(ready_at,now()) WHERE recipe_group_id=v_group;
 SELECT count(DISTINCT language) INTO v_n FROM public.recipes WHERE recipe_group_id=v_group AND published AND nutrition IS NOT NULL;
 IF v_n<>7 THEN RAISE EXCEPTION 'Incomplete seven-language publication'; END IF;
 RAISE NOTICE 'Published group % with seven languages',v_group;
END $publish$;
COMMIT;
